window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"rsVMOdEHpDk","speaker":"Vasile Tofan","role":"Prime Minister","country":"Moldova","region":"Europe","url":"https://www.youtube.com/watch?v=rsVMOdEHpDk","date":"20260926","title":"🇲🇩 Moldova - Prime Minister Addresses United Nations General Debate, 81st Session | #UNGA","seconds":756,"words":1651,"counts":{"claims":24,"promises":4,"attacks":2},"topics":[{"topic":"Ukraine war","share":0.2651,"seconds":201},{"topic":"Moldova sovereignty","share":0.2465,"seconds":186},{"topic":"Moldova EU","share":0.1661,"seconds":126},{"topic":"Moldova Russia","share":0.0822,"seconds":62},{"topic":"Moldova identity","share":0.0811,"seconds":61},{"topic":"Moldova war response","share":0.0795,"seconds":60},{"topic":"Moldova energy","share":0.0794,"seconds":60}],"timeline":[[0,65,"Moldova sovereignty"],[67,129,"Moldova Russia"],[130,190,"Moldova energy"],[191,254,"Moldova EU"],[256,319,"Moldova EU"],[320,382,"Moldova sovereignty"],[383,451,"Ukraine war"],[452,514,"Ukraine war"],[515,585,"Ukraine war"],[586,646,"Moldova war response"],[648,708,"Moldova sovereignty"],[709,770,"Moldova identity"],[771,787,null]],"stances":{"Moldova sovereignty":"Vasile Tofan states that Moldova has transitioned from being a country where others made decisions to one that has decided its own path.","Moldova Russia":"Vasile Tofan describes historical Soviet and Russian interference in Moldova's internal affairs and language, followed by Moldova's independent actions to reduce Russian leverage.","Moldova energy":"Vasile Tofan states that Moldova has increased its renewable energy share to 30% and integrated its grid with Romania and Europe while facing Russian interference.","Moldova EU":"Vasile Tofan states that European integration is Moldova's national project and a choice for democracy, prosperity, and peace.","Ukraine war":"Vasile Tofan describes the normalization of war through children's daily calculations of drone attacks and notes that while Moldova's suffering is less severe, Russian drones have violated its airspace.","Moldova war response":"Vasile Tofan states that Moldova chose to support Ukraine by welcoming refugees and keeping transport routes open, arguing that the outcome of the war matters globally and that Russian forces remain illegally in Transnistria.","Moldova identity":"Vasile Tofan asserts that Moldova is a free and strong nation with capable people and a global diaspora, capable of building a prosperous future despite not being a great power."},"claims":[{"t":40,"quote":"this summer the Republic of Moldova turned 35","topic":"Moldova sovereignty","kind":"fact"},{"t":88,"quote":"Soviet authorities deported our families to Siberia, forced our Romanian language into another alphabet, and told us it had another name.","topic":"Moldova Russia","kind":"fact"},{"t":98,"quote":"After independence, Moscow used gas and trade restrictions as leverage over our Step by step, we began choosing for Romanian is again written in Latin and spoken freely.","topic":"Moldova Russia","kind":"fact"},{"t":124,"quote":"We also reduced Russia's economic leverage on us. We diversified our gas purchases.","topic":"Moldova Russia","kind":"fact"},{"t":130,"quote":"In just 5 years, renewables grew from to around 30% of our energy supply.","topic":"Moldova energy","kind":"number"},{"t":161,"quote":"Russia spent the equivalent of nearly 2% of our GDP trying to influence last year's elections.","topic":"Moldova energy","kind":"number"},{"t":201,"quote":"Moldova has been a candidate country since 2022. Accession negotiations are underway, and we are moving quickly.","topic":"Moldova EU","kind":"fact"},{"t":263,"quote":"A democracy that has learned to resist An emerging economy. A country contributing to stability on Europe's eastern frontier.","topic":"Moldova EU","kind":"fact"},{"t":292,"quote":"With permitting days rather than months, clear regulation, digital public services, and rules that change when they no longer make sense.","topic":"Moldova EU","kind":"fact"},{"t":343,"quote":"We may never have the deepest pools of capital or the largest GPU clusters, but we can build better rules and be more agile.","topic":"Moldova sovereignty","kind":"fact"},{"t":352,"quote":"Smallness does not have to mean weakness. Sometimes, it means turning faster and delivering when larger countries cannot.","topic":"Moldova sovereignty","kind":"fact"},{"t":383,"quote":"Kyiv was home for nearly 15 years, including on that fateful morning of 24th of February 2022.","topic":"Ukraine war","kind":"fact"},{"t":391,"quote":"That morning, as parents, we struggled to explain to our three boys at the time, 1 10 and 12, what war actually","topic":"Ukraine war","kind":"fact"},{"t":410,"quote":"A jet-powered Shahed drone is reported towards Kyiv. A 12-year-old checks the map, knows roughly how fast it is traveling, and does the math in his head.","topic":"Ukraine war","kind":"fact"},{"t":441,"quote":"Yet Russian drones have repeatedly violated our airspace and fallen on our","topic":"Ukraine war","kind":"fact"},{"t":474,"quote":"I know many of you are anxiously following the news about the war next and the growing threat from Russian drones and are already thinking about the winter ahead.","topic":"Ukraine war","kind":"fact"},{"t":487,"quote":"a difficult winter awaits us.","topic":"Ukraine war","kind":"fact"},{"t":554,"quote":"Russia launched a war of aggression against a sovereign neighbor. It occupied territory and continued to attack Ukrainian cities.","topic":"Ukraine war","kind":"fact"},{"t":563,"quote":"Ukraine did not choose this war. Russia did.","topic":"Ukraine war","kind":"fact"},{"t":601,"quote":"We welcomed people fleeing the war. We kept transport routes open. We reduced the cost of rail transit for Ukrainian cargo with grain.","topic":"Moldova war response","kind":"fact"},{"t":640,"quote":"Russian military forces remain illegally and without our consent in the Transnistrian region of Moldova.","topic":"Moldova war response","kind":"fact"},{"t":648,"quote":"We will continue to seek their unconditional withdrawal and the peaceful reintegration of our country with full respect for Moldova's sovereignty and territorial integrity.","topic":"Moldova sovereignty","kind":"fact"},{"t":673,"quote":"Moldova is honored to present its candidacy for the presidency of the 82nd session of the United Nations General Assembly.","topic":"Moldova sovereignty","kind":"fact"},{"t":745,"quote":"We quietly suspect our wines might just be the best in the world.","topic":"Moldova identity","kind":"fact"}],"promises":[{"t":313,"quote":"We want Moldova to become a place where emerging technologies can be tested responsibly through regulatory sandboxes.","topic":"Moldova EU","kind":"promise"},{"t":488,"quote":"Our duty as a government is to prepare and to help those who need it most. That is what we are working on and that is what we are discussing with our partners here.","topic":"Ukraine war","kind":"promise"},{"t":648,"quote":"We will continue to seek their unconditional withdrawal and the peaceful reintegration of our country with full respect for Moldova's sovereignty and territorial integrity.","topic":"Moldova sovereignty","kind":"promise"},{"t":683,"quote":"We want to contribute to a UN that is more effective, more inclusive, and focused on results.","topic":"Moldova sovereignty","kind":"promise"}],"attacks":[{"t":152,"quote":"But the Kremlin kept trying. Moldova faced illicit financing, disinformation, cyber attacks, and vote Russia spent the equivalent of nearly 2% of our GDP trying to influence last year's elections.","topic":"Moldova energy","target":"Russia"},{"t":554,"quote":"Russia launched a war of aggression against a sovereign neighbor.","topic":"Ukraine war","target":"Russia"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":0,"topic":"Moldova sovereignty","text":"to thank the representative from Cabo Verde for delivering that statement in Cabo Verde Creole. &gt;&gt; His Excellency Vasile Talpan, Prime Minister of the Republic of I request protocol to escort His Excellency and invite him to address the &gt;&gt; Vice President, Deputy Secretary General, Excellencies, ladies and gentlemen, this summer the Republic of Moldova turned 35. For much of that time, the world described us as a country caught between East and West, a place where others decided. I stand here as the new Prime Minister of a country that has decided. Small countries do not choose their geography or their size, but small does not mean powerless."},{"t":67,"topic":"Moldova Russia","text":"Nations, like people, are shaped by the choices they make. Whom they trust, whom they elect, whom they call friends, and how they respond when things turn against them. For a long time, others made many of those choices for Soviet authorities deported our families to Siberia, forced our Romanian language into another alphabet, and told us it had another name. After independence, Moscow used gas and trade restrictions as leverage over our Step by step, we began choosing for Romanian is again written in Latin and spoken freely. Governments change peacefully at the ballot box, and when our democracy was threatened, moldovans have defended it through elections and civic action. We also reduced Russia's economic leverage on us. We diversified our gas purchases."},{"t":130,"topic":"Moldova energy","text":"In just 5 years, renewables grew from to around 30% of our energy supply. Our electricity system is increasingly integrated with Romania and the European grid. And our companies sell on some of the most demanding markets in Europe and the But the Kremlin kept trying. Moldova faced illicit financing, disinformation, cyber attacks, and vote Russia spent the equivalent of nearly 2% of our GDP trying to influence last year's elections. Moldovans answered that their home is not for sale. Each of these choices carried a cost, but each taught us the same lesson. We cannot control everything around us, but what we do still matters. That is the source of our optimism. Our future remains in our hands."},{"t":191,"topic":"Moldova EU","text":"And nowhere is that choice clearer today than in our European path. European integration has become our national project. Moldova has been a candidate country since 2022. Accession negotiations are underway, and we are moving quickly. Our ambition is clear, to anchor Moldova firmly in the European family. For us, joining the European Union is not about replacing one sphere of influence with another. It is the It is our citizens exercising their right to choose. Choose democracy, choose prosperity, choose peace. The European choice goes hand in hand with a strong transatlantic partnership. For Moldova, these are not competing directions. The United States has been an important partner in strengthening our security, energy independence, and resilience. We want the next chapter of that relationship to be increasingly about trade, investment, technology, and building things together."},{"t":256,"topic":"Moldova EU","text":"But membership is not only about what Europe can give Moldova. It is also about what Moldova can bring. A democracy that has learned to resist An emerging economy. A country contributing to stability on Europe's eastern frontier. And a small state willing to experiment, reform, and move quickly. Being small imposes constraints, but can it can also be an advantage. Moldova is not a huge domestic market. We cannot outspend the largest So, we have to compete differently. With permitting days rather than months, clear regulation, digital public services, and rules that change when they no longer make sense. Technology is moving faster than regulation almost everywhere. And artificial intelligence is widening that gap. Small countries can have a natural edge We want Moldova to become a place where emerging technologies can be tested responsibly through regulatory sandboxes."},{"t":320,"topic":"Moldova sovereignty","text":"Where regulators learn alongside companies. Rules adjust with evidence. And good ideas do not wait years to reach the real economy. When an entrepreneur arrives with a technology for which the law has not caught up yet, the answer should not simply be there is no rule for this. It should be let us find a safe way to test We may never have the deepest pools of capital or the largest GPU clusters, but we can build better rules and be more agile. Smallness does not have to mean weakness. Sometimes, it means turning faster and delivering when larger countries cannot. And that leads to a broader point about small nations. Power has never been equal. It never will be. But inequality of power must never become inequality of sovereignty. Countries are not buffers. Nations are not bargaining chips. Safety is not abstract to me."},{"t":383,"topic":"Ukraine war","text":"Kyiv was home for nearly 15 years, including on that fateful morning of 24th of February 2022. That morning, as parents, we struggled to explain to our three boys at the time, 1 10 and 12, what war actually Perhaps nothing captures the normalization of this war better than the arithmetic children have learned. Think of a typical night. A jet-powered Shahed drone is reported towards Kyiv. A 12-year-old checks the map, knows roughly how fast it is traveling, and does the math in his head. Perhaps 40 more minutes. 40 more minutes of sleep before approaching drone sends him to the bomb Children have become frighteningly good at this, the nightly arithmetic of war. In Moldova, we cannot begin to compare our suffering with Ukraine's. Yet Russian drones have repeatedly violated our airspace and fallen on our The danger is that the unacceptable starts to feel normal."},{"t":452,"topic":"Ukraine war","text":"For us, too, this is about the safety of our families. We must not grow accustomed to it. Repetition does not make violation acceptable. And because these are not abstract questions for Moldovans watching at home, allow me to speak to them directly for a moment. Dragii &gt;&gt; My fellow Moldovans, I know many of you are anxiously following the news about the war next and the growing threat from Russian drones and are already thinking about the winter ahead. a difficult winter awaits us. Our duty as a government is to prepare and to help those who need it most. That is what we are working on and that is what we are discussing with our partners here. But I want to ask something important of you. Let us stick together. In difficult times, this is what has always helped us through."},{"t":515,"topic":"Ukraine war","text":"Being there for one another, helping our neighbors, our parents, and those struggling the most. We may hold different views. We may vote That is a na- That is natural in a country where people think freely, but caring for those around us must unite us. We are small country. That makes it all the more important to know that we are not alone and that we can count on one another. &gt;&gt; That solidarity at home must go hand in hand with clarity about the danger around us. This is not a tragedy without an author. Russia launched a war of aggression against a sovereign neighbor. It occupied territory and continued to attack Ukrainian cities. Ukraine did not choose this war. Russia did. We often speak about war fatigue. The phrase is understandable. Governments have other crises. Families have their own worries. Attention moves But being tired of a worry you can switch off is different from being tired because of an air raid wakes your children at night."},{"t":586,"topic":"Moldova war response","text":"And different still from the exhaustion of Ukrainian spending another cold night in the mud. Moldova could not choose that this war began next to us. But we could choose our response. We welcomed people fleeing the war. We kept transport routes open. We reduced the cost of rail transit for Ukrainian cargo with grain. These decisions were not always or politically easy at home. We made them because the way this war ends matters to us far beyond our region. If aggression is rewarded, it becomes a precedent for the aggressor and for everyone Peace must protect sovereignty and create the conditions for lasting The same principle applies within our own borders. Russian military forces remain illegally and without our consent in the Transnistrian region of Moldova."},{"t":648,"topic":"Moldova sovereignty","text":"We will continue to seek their unconditional withdrawal and the peaceful reintegration of our country with full respect for Moldova's sovereignty and territorial integrity. We want people on both banks of the Nistru to live together in a peaceful, democratic, and prosperous Moldova. And because we believe small states should help shape the international system, not simply depend on it, Moldova is honored to present its candidacy for the presidency of the 82nd session of the United Nations General Assembly. We want to contribute to a UN that is more effective, more inclusive, and focused on results. We live in a world with plenty of reasons for pessimism. Moldova chooses something else. Not naive optimism. Not the belief that problems disappear if we refuse to see them. The optimist that comes from knowing that our future is still in our hands."},{"t":709,"topic":"Moldova identity","text":"For too long Moldovans were told that our country was too small, too exposed, too divided to choose its own future. We have spent enough time believing that. We know our problems, but we should also know our strength. We are a free country. Our people are humble, work hard, and put family first. Our diaspora is spread across the world, but stays close to one another and deeply cares about what happens at home. Only when it comes to vineyards, does modesty become a little harder for us. We quietly suspect our wines might just be the best in the world. We have friends across Europe, across Atlantic, and far beyond. And we finally have a realistic path to build a country our children should not need to leave in search of opportunity. Moldova may never be a great power, but we have everything it takes to be a great country."},{"t":771,"topic":null,"text":"Thank you. &gt;&gt; I on behalf of the assembly, I wish to thank the Prime Minister of the Republic of Moldova. The assembly will hear an address"}],"compare":[{"topic":"Moldova","share":0.326,"mean":0.0004,"rank":1,"others":1},{"topic":"Russia-Ukraine War","share":0.2651,"mean":0.0341,"rank":7,"others":44}]};
